// Mismo patrón que 'Procesar Factura' — extraer contexto tenant.
const d = $json || {};
return {
  apiKey: d.apiKey || '',
  empresaId: d.empresaId || null,
  gemini_credential_id: d.openai_credential_id || d.gemini_credential_id || '',
  file_path: d.file_path || '',
  file_url: d.file_url || '',
  filename: d.filename || '',
  original_filename: d.original_filename || d.filename || '',
  uploaded_at: d.uploaded_at || new Date().toISOString(),
  pdf_base64: d.pdf_base64 || '',
  pdf_mime_type: d.pdf_mime_type || 'application/pdf'
};

// Lee directamente del nodo Webhook — el base64 es largo y a veces
// se pierde en la propagación entre nodos.
const webhookData = $('Webhook — Recibir Adjunto').item.json;
const data = webhookData.body || webhookData;

const base64 = data.pdf_base64 || $json.pdf_base64 || '';
const mimeType = data.pdf_mime_type || $json.pdf_mime_type || 'application/pdf';
const fileName = data.original_filename || $json.original_filename || 'factura.pdf';

if (!base64 || base64.length < 100) {
  throw new Error(
    `pdf_base64 vacío o muy corto (length=${base64.length}). ` +
    `Verifica que el backend embeba el PDF en el payload del webhook (helper build_email_process_payload).`
  );
}

return {
  json: $json,
  binary: {
    data: {
      data: base64,
      mimeType: mimeType,
      fileName: fileName,
      fileExtension: 'pdf'
    }
  }
};

const ctx = $('Extraer Contexto Tenant').item.json;
const response = $json || {};

let text = '';
if (typeof response === 'string') {
  text = response;
} else if (typeof response.content?.parts?.[0]?.text === 'string') {
  text = response.content.parts[0].text;
} else if (typeof response.candidates?.[0]?.content?.parts?.[0]?.text === 'string') {
  text = response.candidates[0].content.parts[0].text;
} else if (typeof response.text === 'string') {
  text = response.text;
} else if (typeof response.response === 'string') {
  text = response.response;
} else if (typeof response.output === 'string') {
  text = response.output;
} else if (typeof response.message?.content === 'string') {
  text = response.message.content;
}

try {
  if (!text) {
    throw new Error('No se encontró texto. Keys: ' + Object.keys(response).join(', '));
  }

  let jsonStr = text.trim();
  const m = jsonStr.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (m) jsonStr = m[1].trim();
  const firstBrace = jsonStr.indexOf('{');
  const lastBrace = jsonStr.lastIndexOf('}');
  if (firstBrace >= 0 && lastBrace > firstBrace) {
    jsonStr = jsonStr.substring(firstBrace, lastBrace + 1);
  }

  const datos = JSON.parse(jsonStr);

  return {
    ...datos,
    url_factura: ctx.file_url || ctx.file_path || '',
    apiKey: ctx.apiKey,
    empresaId: ctx.empresaId,
    source_filename: ctx.original_filename,
    extraction_success: true
  };
} catch (error) {
  return {
    error: 'No se pudo parsear: ' + error.message,
    raw_response: JSON.stringify(response).slice(0, 2000),
    extracted_text: (text || '').toString().slice(0, 1000),
    extraction_success: false,
    apiKey: ctx.apiKey,
    empresaId: ctx.empresaId
  };
}
